const {spawnSync} = require("child_process");
const fs = require("fs");
// usage: node run.js -f file    |  node run.js -s 'string'
let a;
if (process.argv[2] === '-f') a = fs.readFileSync(process.argv[3], "utf8");
else a = process.argv[3];
const r = spawnSync("/workspace/dataset/test9_executable", ["--a", a], {encoding: "utf8"});
process.stdout.write("RC=" + r.status + "\n---stdout---\n" + r.stdout + "---end---\n");
if (r.status) process.stdout.write("STDERR-TAIL:\n" + r.stderr.split("\n").slice(-8).join("\n") + "\n");

// Runs many inputs (one per line of a JSON array file, or JSON lines on argv) and prints exact output.
const {spawnSync} = require("child_process");
const fs = require("fs");
const inputs = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
function vis(s) {
  return s.replace(/\t/g, "<TAB>").replace(/ /g, "·").replace(/\n/g, "<NL>\n");
}
for (const inp of inputs) {
  const r = spawnSync("/workspace/dataset/test9_executable", ["--a", inp], {encoding: "utf8"});
  let out;
  if (r.status === 0) out = JSON.stringify(r.stdout);
  else {
    const lines = r.stderr.trim().split("\n");
    out = "ERR rc=" + r.status + " :: " + lines.slice(-6).join(" | ");
  }
  process.stdout.write(JSON.stringify(inp) + "\n    => " + out + "\n");
}

