const {spawnSync}=require("child_process");
function run(a){const r=spawnSync("/workspace/dataset/test9_executable",["--a="+a],{encoding:"utf8"});return r.status?("ERR "+r.stderr.trim().split("\n").slice(-2)[0]):r.stdout;}
// build base64 of N bytes
for (const n of [56,57,58,59,60,114,115,116,117]) {
  const buf = Buffer.alloc(n); for(let i=0;i<n;i++) buf[i]=65+(i%26);
  const b64 = buf.toString("base64");
  const out = run("!!binary "+b64);
  const lines = out.split("\n");
  console.log("nbytes="+n+" b64len="+b64.length+" -> lines:", lines.slice(1,-2).map(l=>l.length+":"+JSON.stringify(l.slice(0,10))));
}
'

